        h3 {
            font-size: 1.3rem;
            color: var(--text-primary);
            margin: 1.5rem 0 1rem;
        }

        .kpi-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
            gap: 1.5rem;
            margin: 2rem 0;
        }

        .kpi-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 1.5rem;
            text-align: center;
            transition: transform 0.2s, box-shadow 0.2s;
        }

        .kpi-card:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 25px rgba(0,0,0,0.3);
        }

        .kpi-label {
            font-size: 0.85rem;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--text-muted);
            margin-bottom: 0.5rem;
        }

        .kpi-value {
            font-size: 2rem;
            font-weight: 700;
            color: var(--accent-gold);
        }

        .kpi-value.negative {
            color: var(--negative);
        }

        .kpi-value.positive {
            color: var(--positive);
        }

        .kpi-context {
            font-size: 0.8rem;
            color: var(--text-secondary);
            margin-top: 0.5rem;
        }

        .card {
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 2rem;
            margin: 2rem 0;
        }

        .chart-container {
            position: relative;
            height: 400px;
            margin: 1.5rem 0;
        }

        .chart-container-sm {
            height: 300px;
        }

        .stat-table {
            width: 100%;
            border-collapse: collapse;
            margin: 1rem 0;
        }

        .stat-table th, .stat-table td {
            padding: 0.75rem 1rem;
            text-align: left;
            border-bottom: 1px solid var(--border);
        }

        .stat-table th {
            background: var(--bg-card);
            color: var(--text-secondary);
            font-weight: 600;
            font-size: 0.85rem;
            text-transform: uppercase;
        }

        .stat-table tr:hover {
            background: rgba(255,215,0,0.05);
        }

        .stat-table .positive {
            color: var(--positive);
        }

        .stat-table .negative {
            color: var(--negative);
        }

        .insight-box {
            background: rgba(255, 215, 0, 0.1);
            border-left: 4px solid var(--accent-gold);
            padding: 1rem 1.5rem;
            margin: 1.5rem 0;
            border-radius: 0 8px 8px 0;
        }

        .insight-box h4 {
            color: var(--accent-gold);
            margin-bottom: 0.5rem;
        }

        .regime-legend {
            display: flex;
            gap: 2rem;
            margin: 1rem 0;
            flex-wrap: wrap;
        }

        .regime-item {
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .regime-dot {
            width: 12px;
            height: 12px;
            border-radius: 50%;
        }

        .regime-dot.low { background: var(--regime-low); }
        .regime-dot.medium { background: var(--regime-med); }
        .regime-dot.high { background: var(--regime-high); }

        .month-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 1rem;
        }

        .month-stat {
            background: var(--bg-card);
            border-radius: 8px;
            padding: 1rem;
            text-align: center;
        }

        .month-name {
            font-weight: 600;
            color: var(--text-secondary);
            margin-bottom: 0.5rem;
