            font-size: 0.75rem;
            color: var(--text-muted);
            margin-top: 0.25rem;
        }

        .significant {
            color: var(--accent-gold);
        }

        .distribution-stats {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
            gap: 1rem;
            margin: 1.5rem 0;
        }

        .dist-stat {
            background: var(--bg-card);
            padding: 1rem;
            border-radius: 8px;
            text-align: center;
        }

        .dist-stat-label {
            font-size: 0.8rem;
            color: var(--text-muted);
            margin-bottom: 0.25rem;
        }

        .dist-stat-value {
            font-size: 1.3rem;
            font-weight: 700;
        }

        .takeaway-list {
            list-style: none;
        }

        .takeaway-list li {
            padding: 1rem 0;
            border-bottom: 1px solid var(--border);
            display: flex;
            gap: 1rem;
        }

        .takeaway-list li:last-child {
            border-bottom: none;
        }

        .takeaway-number {
            background: var(--accent-gold);
            color: var(--bg-primary);
            width: 28px;
            height: 28px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 700;
            font-size: 0.9rem;
            flex-shrink: 0;
        }

        .footer {
            margin-top: 4rem;
            padding-top: 2rem;
            border-top: 1px solid var(--border);
            text-align: center;
            color: var(--text-muted);
            font-size: 0.85rem;
        }

        @media (max-width: 768px) {
            .container {
                padding: 1rem;
            }
            h1 {
                font-size: 1.8rem;
            }
            .kpi-grid {
                grid-template-columns: repeat(2, 1fr);
            }
            .month-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }
    </style>
</head>
