    <div class="container">
        <header>
            <h1>Gold Price Dynamics</h1>
            <p class="subtitle">A Comprehensive Trend and Volatility Analysis (2000–2025)</p>
            <p class="subtitle" style="margin-top: 0.5rem; font-size: 0.9rem; color: var(--text-muted);">
                Dataset: 6,399 observations | August 30, 2000 – March 3, 2026
            </p>
        </header>

        <!-- KEY KPIs SECTION -->
        <section class="card">
