                    </tr>
                    <tr>
                        <td>August</td>
                        <td class="positive">+1.07%</td>
                        <td>0.0358</td>
                        <td class="significant">Yes (p < 0.05)</td>
                    </tr>
                    <tr>
                        <td>September</td>
